window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1906372458c62b87"]={"versions": [{"id": "FIG-1906372458c62b87", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Methodik-Diagramm der AUTOSAR Methodology (<code>AUTOSAR_TR_Methodology</code>). Das Diagramm spezifiziert die methodische Aktivität zur Erstellung administrativer Metadaten innerhalb des AUTOSAR-Entwicklungsprozesses sowie das resultierende Beschreibungs-Artefakt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Define Admin Data</strong>: Methodische Entwurfsaktivität (dargestellt als spitz zulaufender Block/Aktivitätssymbol).\n</li><li><strong>General Autosar...</strong> (General Autosar Description): Spezifikations- bzw. Modellierungsartefakt (Dokumentsymbol), welches das Arbeitsergebnis darstellt.\n</li><li><strong>«output»</strong>: Gerichtete Datenflussbeziehung von der Aktivität zum Artefakt mit der Kardinalität <code>1</code> am Zielelement.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführung der Aktivität <code>Define Admin Data</code> erzeugt verbindlich genau eine Instanz des Ausgabeartefakts (<code>General Autosar Description</code>). Es existieren im Schaubild keine dargestellten Eingangsartefakte oder Folgeaktivitäten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurations- und Modellierungswerkzeuge müssen bei Ausführung des Methodikschritts administrative Daten (wie Versionshistorie, Bearbeiter, Dokumentenstatus oder Freigaben gemäß AUTOSAR-Metamodell) in der resultierenden AUTOSAR-XML-Beschreibung hinterlegen. Die Kardinalität <code>1</code> definiert die strikte Verpflichtung zur Ausgabe des Artefakts.</p>"}, {"id": "FIG-ba0e27e57771d3b2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Methodik-Diagramm der AUTOSAR Methodology (<code>AUTOSAR_TR_Methodology</code>). Das Diagramm spezifiziert die methodische Aktivität zur Erstellung administrativer Metadaten innerhalb des AUTOSAR-Entwicklungsprozesses sowie das resultierende Beschreibungs-Artefakt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Define Admin Data</strong>: Methodische Entwurfsaktivität (dargestellt als spitz zulaufender Block/Aktivitätssymbol).\n</li><li><strong>General Autosar...</strong> (General Autosar Description): Spezifikations- bzw. Modellierungsartefakt (Dokumentsymbol), welches das Arbeitsergebnis darstellt.\n</li><li><strong>«output»</strong>: Gerichtete Datenflussbeziehung von der Aktivität zum Artefakt mit der Kardinalität <code>1</code> am Zielelement.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Ausführung der Aktivität <code>Define Admin Data</code> erzeugt verbindlich genau eine Instanz des Ausgabeartefakts (<code>General Autosar Description</code>). Es existieren im Schaubild keine dargestellten Eingangsartefakte oder Folgeaktivitäten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurations- und Modellierungswerkzeuge müssen bei Ausführung des Methodikschritts administrative Daten (wie Versionshistorie, Bearbeiter, Dokumentenstatus oder Freigaben gemäß AUTOSAR-Metamodell) in der resultierenden AUTOSAR-XML-Beschreibung hinterlegen. Die Kardinalität <code>1</code> definiert die strikte Verpflichtung zur Ausgabe des Artefakts.</p>"}], "trans": [{"from": "FIG-1906372458c62b87", "to": "FIG-ba0e27e57771d3b2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
